use std::time::Duration;
use trpl::{Either, ReceiverStream, StreamExt};

fn main() {
    trpl::block_on(async {
        let (tx, rx) = trpl::channel();
        let producer = async move {
            tx.send(1).expect("sent");
            trpl::sleep(Duration::from_millis(600)).await;
            tx.send(2).expect("sent");
        };
        let consumer = async {
            let mut stream = ReceiverStream::new(rx);
            loop {
                let next = stream.next();
                match trpl::select(next, trpl::sleep(Duration::from_millis(150))).await {
                    Either::Left(Some(n)) => println!("item {n}"),
                    Either::Left(None) => break,
                    Either::Right(()) => {
                        println!("idle, stopping");
                        break;
                    }
                }
            }
        };
        trpl::join(producer, consumer).await;
    });
}

