        let this = self.get_mut();
        this.polls += 1;
        if this.pending > 0 {
            this.pending -= 1;
            cx.waker().wake_by_ref();
            Poll::Pending
        } else {
            Poll::Ready((this.value, this.polls))
        }
    }
}

